package com.nextfeet.nextfeet.model; public class Usuario { private Integer id; private String nombres,apellidos,correo,password,telefono,rol,estado; public Usuario(){} public Usuario(Integer id,String nombres,String apellidos,String correo,String password,String telefono,String rol,String estado){this.id=id;this.nombres=nombres;this.apellidos=apellidos;this.correo=correo;this.password=password;this.telefono=telefono;this.rol=rol;this.estado=estado;} public Integer getId(){return id;} public void setId(Integer v){id=v;} public String getNombres(){return nombres;} public void setNombres(String v){nombres=v;} public String getApellidos(){return apellidos;} public void setApellidos(String v){apellidos=v;} public String getCorreo(){return correo;} public void setCorreo(String v){correo=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getTelefono(){return telefono;} public void setTelefono(String v){telefono=v;} public String getRol(){return rol;} public void setRol(String v){rol=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }